def clean(s):return str(s).replace('\u2011','-').replace('\u2013','-').replace('\u2014','-')
def para(text,style='body'):return Paragraph(escape(clean(text)).replace('\n','<br/>'),styles[style])
story=[]
def p(text):story.append(para(text))
def h(text):story.append(para(text,'h2'))
def note(text):
    box=Table([[para(text)]],colWidths=[495]);box.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,-1),LIGHT),('BOX',(0,0),(-1,-1),.6,colors.HexColor('#d6e4f4')),('LEFTPADDING',(0,0),(-1,-1),12),('RIGHTPADDING',(0,0),(-1,-1),12),('TOPPADDING',(0,0),(-1,-1),10),('BOTTOMPADDING',(0,0),(-1,-1),3)]));story.extend([box,Spacer(1,12)])
def steps(*items):
    for i,item in enumerate(items,1):story.append(para(f'{i}. {item}'))
def bullets(*items):
    for item in items:story.append(para('• '+item))
def code(text):story.append(Preformatted(clean(text.strip()),styles['code'],maxLineLength=96))
def table(headers,rows,widths=None):
    widths=widths or [495/len(headers)]*len(headers)
    data=[[para(c,'th') for c in headers]]+[[para(c,'cell') for c in row] for row in rows]
    t=Table(data,colWidths=widths,repeatRows=1,hAlign='LEFT');t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),BLUE),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#f4f7fb')]),('VALIGN',(0,0),(-1,-1),'TOP'),('LINEBELOW',(0,0),(-1,0),.5,BLUE),('BOTTOMPADDING',(0,0),(-1,-1),9),('TOPPADDING',(0,0),(-1,-1),9),('LEFTPADDING',(0,0),(-1,-1),9),('RIGHTPADDING',(0,0),(-1,-1),9)]));story.extend([t,Spacer(1,12)])
def chapter(num,title):story.extend([PageBreak(),para(f'{num:02d}. {title}','h1')])

class Floors(Flowable):
    def __init__(self):Flowable.__init__(self);self.width=495;self.height=200
    def draw(self):
        c=self.canv;c.setFillColor(BLUE);c.roundRect(150,166,195,28,6,fill=1,stroke=0);c.setFillColor(colors.white);c.setFont('BodyBold',12);c.drawCentredString(247.5,176,'Одна компания')
        c.setStrokeColor(colors.HexColor('#b6cbe4'));c.line(247,166,247,153);c.line(120,153,375,153)
        for x,title,labels in [(0,'Филиал «Центральный»',['1-й этаж','2-й этаж']),(255,'Филиал «Северный»',['Зона А','Зона Б'])]:
            c.line(x+120,153,x+120,144);c.setFillColor(LIGHT);c.roundRect(x,114,240,30,6,fill=1,stroke=0);c.setFillColor(BLUE);c.setFont('BodyBold',11);c.drawCentredString(x+120,125,title)
            c.line(x+120,114,x+120,102);c.line(x+57,102,x+182,102)
            for n,label in enumerate(labels):
                px=x+5+n*125;c.line(px+52,102,px+52,93);c.setFillColor(LIGHT);c.roundRect(px,24,105,69,6,fill=1,stroke=0);c.setFillColor(BLUE);c.setFont('BodyBold',10);c.drawCentredString(px+52,73,'Точка '+str(n+1));c.setFont('Body',9);c.drawCentredString(px+52,54,label);c.setFillColor(INK);c.setFont('Body',8);c.drawCentredString(px+52,36,'Своя очередь')


class Guide(BaseDocTemplate):
    def __init__(self,path):
        super().__init__(str(path),pagesize=A4,leftMargin=50,rightMargin=50,topMargin=60,bottomMargin=49,title='Kezek: руководство от А до Я',author='Kezek',subject='Установка, точки по этажам, подключение и работа')
        self.addPageTemplates(PageTemplate(id='guide',frames=[Frame(50,49,495,A4[1]-109,id='body',leftPadding=0,rightPadding=0,topPadding=0,bottomPadding=0)],onPage=self.page))
    def page(self,c,doc):
        c.saveState()
        if doc.page>1:
            c.setFont('BodyBold',9);c.setFillColor(BLUE);c.drawString(50,A4[1]-33,'KEZEK  /  РУКОВОДСТВО')
            c.setFont('Body',8);c.setFillColor(MUTED);c.drawRightString(545,A4[1]-33,'Runtime 1.1.0  |  26.10.2026')
        c.setStrokeColor(colors.HexColor('#dbe4ef'));c.line(50,37,545,37);c.setFont('Body',8);c.setFillColor(MUTED);c.drawString(50,23,'Установка • Подключение • Ежедневная работа');c.drawRightString(545,23,str(doc.page));c.restoreState()
    def afterFlowable(self,f):
        if isinstance(f,Paragraph) and f.style.name=='Chapter':
            text=f.getPlainText();key='chapter-'+text.split('.')[0];self.canv.bookmarkPage(key);self.canv.addOutlineEntry(text,key,0);self.notify('TOCEntry',(0,text,self.page,key))

story.extend([Spacer(1,65),para('KEZEK','cover'),para('Электронная очередь\nРуководство от А до Я','cover'),para('Для владельца платформы, установщика, администратора компании и сотрудника'),Spacer(1,25),Floors(),Spacer(1,20)])
note('Компания имеет несколько филиалов; каждый филиал имеет несколько точек обслуживания. Этаж - только пример точки. У каждой точки отдельные услуги, сотрудники, устройства и очередь.')
p('Актуальная модель: услуги и подуслуги назначаются сотрудникам напрямую, без столов. Документ описывает фактические возможности проекта на 26 октября 2026 года. Рабочие пароли, приватные ключи и реальные токены в этот PDF не включены.')
story.append(para('Версии: Runtime 1.1.0 / протокол 2; Control Plane / протокол 1.','small'))
story.extend([PageBreak(),para('Содержание','cover')]);toc=TableOfContents();toc.levelStyles=[ParagraphStyle('TOC',fontName='Body',fontSize=9,leading=12.5,textColor=INK,leftIndent=0,firstLineIndent=0,spaceBefore=0,spaceAfter=0)];story.append(toc)

chapter(1,'Как устроена система')
p('В платформе два независимых приложения. Control Plane - закрытая супер-админка владельца. Runtime - рабочая система компании: терминалы, дисплеи, сотрудники, услуги, очередь и отчёты. У них разные backend и базы PostgreSQL.')
table(['Компонент','Назначение'],[['Control Plane, порт 3002','Компании, реестр точек и установок, токены, устройства, аудит и каталог релизов. Списков сотрудников здесь нет.'],['Runtime, порт 3001','Повседневная очередь одной или нескольких компаний с изоляцией точек. Может находиться на вашем сервере или у заказчика.'],['Браузеры','Терминал выдаёт талон; дисплей показывает вызовы; сотрудник работает под личным логином. EXE, APK и Electron не нужны.']], [150,345])
p('Runtime продолжает выдавать, вызывать и обслуживать талоны при недоступности Control Plane, GitHub или внешнего интернета, если его сервер, локальная сеть и база доступны. Отключение самого сервера или базы останавливает обслуживание до восстановления.')
note('Иерархия: Company → CompanyBranch → Branch. CompanyBranch - отдельный филиал, Branch - точка внутри него. Старое техническое имя Branch сохранено ради истории и постоянных ID устройств; в интерфейсе филиал и точка теперь разные сущности.')

chapter(2,'Филиалы и их точки: пример здания')
story.append(Floors())
table(['Точка','Пример услуг','Оборудование'],[['CENTRAL / FLOOR1','Коммунальные услуги / Вода / Электричество','1-й этаж: терминал, дисплей и сотрудники'],['CENTRAL / FLOOR2','Справки / Документы','2-й этаж: отдельные устройства и очередь'],['NORTH / P1','Другие услуги','Точка филиала Северный']], [140,180,175])
p('Создайте компанию, затем её филиалы, затем точки в каждом филиале. Количество точек не ограничено двумя: этажи, корпуса, зоны и направления - примеры. Одинаковая услуга в разных точках создаётся отдельно; совпадение названия не объединяет очередь.')
bullets('Администратор компании видит все её точки и переключается между ними.','Администратор точки и сотрудник видят только назначенные им точки.','Терминал и дисплей не выбирают чужую точку после регистрации. Для переноса устройство отзывают и регистрируют заново.','Нумерация отдельная для точки, дня и префикса. A001 на двух этажах может быть двумя разными талонами.')

chapter(3,'Что подготовить до установки')
table(['Нужно','Практическое требование'],[['Сервер','64-битная система, Node.js 22+, PostgreSQL 16+ с UTF8; либо Docker Engine с Compose.'],['Диск','Постоянное хранилище базы, конфигурации и резервных копий. Объём проверяется по реальной нагрузке и сроку хранения.'],['Сеть','Стабильная LAN для устройств. Для внешнего доступа - домен и HTTPS. Для сервера желательно резервное питание.'],['Клиенты','Современный браузер; постоянный отдельный профиль для каждого терминала или дисплея. Для печати - драйвер 80-мм принтера.'],['Ответственные','Владелец ключей, установщик, администратор компании и человек, проверяющий backup/restore.']], [130,365])
p('Не размещайте backend на хостинге, который поддерживает только PHP и статические файлы. Нужны постоянные Node.js-процессы и PostgreSQL. Копия сайта без API и базы не является работающей очередью.')
p('Перед внедрением запишите: адреса серверов, точки/этажи, список услуг, сотрудников и назначений, количество устройств, принтеры, часовой пояс, режим передачи данных и согласованное окно обслуживания.')
note('В этой среде проверена локальная демонстрация. Реальное внешнее размещение, Docker-развёртывание, оборудование принтера и полный production-update ещё требуют репетиции на выбранном сервере.')

chapter(4,'Выбор размещения')
h('Вариант А: ваш сервер')
p('Control Plane размещается на вашем адресе. Runtime можно разместить на вашем же VPS, но отдельным приложением и с отдельной базой. Все этажи компании используют один Runtime, а изоляция выполняется по точкам. Клиентам нужен доступ к этому серверу.')
h('Вариант Б: локальный сервер заказчика')
p('Runtime и его база находятся в здании. Терминалы, дисплеи и сотрудники подключаются к нему по LAN. Внешняя сеть нужна только для разрешённых синхронизаций и обновлений. При отсутствии интернета локальная очередь продолжает работать.')
h('Независимые локальные серверы')
p('Если каждому объекту установлен отдельный Runtime, это отдельные оперативные очереди. Система не изображает их общим онлайн-потоком. Администратор работает в админке нужной установки; Control Plane показывает её последнее известное техническое состояние.')
note('Для здания обычно достаточно одного Runtime, одного филиала и нескольких его точек. Другой филиал той же компании имеет собственный набор точек. Отдельная база на каждый этаж не требуется.')

chapter(5,'Ключи и конфигурация')
p('Для production разделите окружения: .env.control - только Control Plane, .env.runtime - Runtime. Общая корневая .env предназначена для локальной разработки. Копируйте примеры, а не конфигурацию с чужими секретами.')
code(r'''openssl genpkey -algorithm ED25519 -out control-private.pem
openssl pkey -in control-private.pem -pubout -out control-public.pem
openssl genpkey -algorithm ED25519 -out release-private.pem
openssl pkey -in release-private.pem -pubout -out release-public.pem''')
bullets('Control private key хранится у владельца платформы. Runtime получает только control public key.','Release private key остаётся на машине выпуска обновлений. Runtime получает release public key.','Пароли баз, SETUP_SECRET, BRIDGE_TOKEN и OWNER_PASSWORD генерируйте индивидуально; не используйте CHANGE_ME из примеров.','Закройте доступ к .env, ключам, backup и .local средствами ОС. Они не должны лежать в публичном web-root.')
p('Дату и локальную нумерацию определяет IANA timezone, например Asia/Qyzylorda. COOKIE_SECURE=true включается при HTTPS. Значения origins задаются полными адресами, через запятую, без завершающего слеша.')

chapter(6,'Установка через Docker Compose')
p('Подготовьте исходники проекта и Docker. Следующие действия выполняются из корня проекта. Предварительно задайте секреты и реальные пути к ключам.')
code(r'''cp .env.compose.example .env.compose
cp .env.runtime.example .env.runtime
cp .env.control.example .env.control
docker compose --env-file .env.compose up -d --build
docker compose --env-file .env.compose ps''')
p('В .env.compose задайте разные URL-safe пароли баз и пути к ключам. В .env.runtime/.env.control - origins, порты, секрет установщика и политику обмена. Compose создаёт отдельные базы, migration jobs, сервисы и тома; приватный ключ Control Plane не монтируется в Runtime.')
code(r'''docker compose --env-file .env.compose run --rm control \
  node --import tsx scripts/create-owner.ts''')
p('Для команды первого владельца в .env.control заранее заполните OWNER_LOGIN и OWNER_PASSWORD длиной от 12 символов. После создания уберите постоянный OWNER_PASSWORD. Если владелец уже существует, CLI не создаёт второго автоматически.')
note('Не запускайте demo-bootstrap на production. Compose подготовлен, но в текущей среде не запускался: сначала проверьте его на staging и выполните приёмку из главы 26.')

chapter(7,'Установка без Docker и локальный запуск')
p('Установите Node.js 22+ и PostgreSQL, создайте две UTF8-базы и отдельных пользователей с доступом только к своим базам. Для локальной разработки заполните .env по .env.example.')
code(r'''npm ci
npm run build
npm run migrate''')
p('Для production миграции можно выполнять раздельно, не передавая Runtime пароль базы Control Plane:')
code(r'''node --env-file=.env.runtime node_modules/prisma/build/index.js \
  migrate deploy --schema db/runtime/schema.prisma
node --env-file=.env.control node_modules/prisma/build/index.js \
  migrate deploy --schema db/control/schema.prisma''')
p('Запустите два независимых процесса под supervisor (например systemd). Укажите правильный WorkingDirectory, автозапуск после перезагрузки, путь Node и отдельные журналы. Команды процессов:')
code(r'''node --env-file=.env.runtime apps/runtime-api/dist/index.js
node --env-file=.env.control apps/control-api/dist/index.js''')
p('Только для демонстрации допустим npm run bootstrap: создаются две компании, роли и индивидуальные пароли в .local/demo-credentials.json. Повторный bootstrap не предназначен для сброса паролей.')

chapter(8,'Домен, локальная сеть и HTTPS')
p('Пример: owner.example.kz направляется на Control Plane:3002, queue.example.kz - на Runtime:3001. Настройте DNS, действительный TLS-сертификат и reverse proxy. Frontend и API одной части предпочтительно размещать на одном origin.')
table(['Ситуация','Адрес в браузере'],[['На этом сервере','http://localhost:3001/terminal'],['На другом устройстве в LAN','http://192.168.10.10:3001/terminal - пример, подставьте IP сервера'],['Внешнее размещение','https://queue.example.kz/terminal']], [175,320])
p('На терминале localhost означает сам терминал, а не центральный сервер. Закрепите IP сервера через DHCP reservation или статическую настройку. В RUNTIME_ORIGINS включите фактический адрес открытия Runtime; при LAN-доступе HOST должен разрешать прослушивание интерфейса, например 0.0.0.0.')
bullets('Внешний вход обычно разрешают только на 443. PostgreSQL не публикуют в интернет.','Для LAN ограничьте доступ разрешённой подсетью. HTTP оставляйте только в доверенной сети; предпочтителен внутренний HTTPS.','Для Socket.IO proxy должен поддерживать WebSocket Upgrade. При его отсутствии работает polling.','Не задавайте trust proxy=true для произвольных источников. За proxy настройте конкретную доверенную схему адресации и rate limit.')

chapter(9,'Первый владелец и супер-админка')
p('Первый владелец создаётся только CLI-командой, публичной регистрации нет. Вход: /owner на адресе Control Plane. Дополнительного владельца добавляет вошедший владелец в разделе «Владельцы платформы».')
table(['Раздел','Для чего'],[['Компании','Название и логин первого администратора; разрешение новых подключений.'],['Филиалы','Отдельные подразделения компании: код, название, адрес.'],['Точки обслуживания','Этажи, корпуса и зоны внутри выбранного филиала.'],['Установки','Cloud/local, адрес, managed/isolated, разрешённые компании и точки.'],['Токены подключения','Коды устройств, типы, срок, лимит и файл активации.'],['Устройства, аудит, обновления','Последнее известное состояние, отзыв, действия владельца и каталог релизов.']], [150,345])
p('Данные сотрудников и их пароли в Control Plane не передаются. Учётными записями управляет администратор компании в Runtime. Супер-админка не должна служить публичной страницей для посетителей.')

chapter(10,'Компания, установка и активация Runtime')
steps('В Control Plane создайте компанию: название и логин её первого администратора.','Создайте филиалы компании, затем точки внутри каждого филиала, если ведёте централизованный реестр.','Создайте установку: cloud/local, managed/isolated, URL Runtime, список компаний и точек. Сохраните ID и выданный bridgeToken.','Создайте токен подключения для установки и скачайте подписанный JSON активации.','В .env.runtime задайте INSTALLATION_ID, CONTROL_PUBLIC_KEY_FILE и собственный SETUP_SECRET. Для обмена дополнительно задайте BRIDGE_URL/TOKEN. Перезапустите Runtime.','Откройте Runtime /setup, введите секрет установщика и загрузите JSON. Сохраните выданный временный пароль первого администратора.','Войдите в /admin и смените временный пароль.')
note('Подписанный файл активирует локальную установку. Короткий 8-значный токен регистрирует устройства уже активированного Runtime. Это разные шаги; одного короткого кода для развёртывания пустого сервера недостаточно.')
p('Активация проверяется локально по подписи, сроку и ID установки; интернет в этот момент не обязателен. Повторный импорт не сбрасывает существующие пароли и не восстанавливает отозванный регистрационный токен.')

chapter(11,'Настроить два этажа: пошагово')
steps('В админке открыть «Организация → Филиалы» и создать филиал CENTRAL. Затем у него нажать «Точки обслуживания» либо открыть этот раздел меню.','Нажать «Добавить точку», выбрать филиал CENTRAL, создать FLOOR1 с названием «1-й этаж - коммунальные услуги». Указать адрес здания и этаж.','Создать FLOOR2 с названием «2-й этаж - другие услуги», также внутри CENTRAL. Для другого филиала создать его отдельно и добавить в него свои точки.','В верхних переключателях выбрать сначала филиал CENTRAL, затем первую точку. Создать её услуги и подуслуги.','Переключиться на вторую точку и создать её услуги. Они не попадут на терминал первой.','Назначить сотрудникам нужные точки и услуги. Работнику только первого этажа не назначать второй.','В каждой точке выпустить свой код подключения устройств и зарегистрировать терминал/дисплей нужного этажа.','Выдать по талону на каждом этаже и выполнить взаимную проверку экранов: чужой талон не должен появиться.')
p('Если создаёте точки в Control Plane до активации, они попадут в подписанный пакет с теми же ID. Локально созданные в Runtime точки работают сразу; коды для них выпускайте админкой компании. Автоматической синхронизации новых локальных точек в реестр Control Plane сейчас нет.')
note('В одном филиале может быть несколько точек, в другом - другое количество. Коды точек уникальны внутри филиала: P1 в CENTRAL и P1 в NORTH допустимы. Права и очереди привязаны к ID точки, а не её названию.')

chapter(12,'Услуги и подуслуги')
p('Откройте «Организация → Услуги» в выбранной точке. Создайте название на RU/KK/EN, уникальный префикс и активность. «Добавить подуслугу» создаёт вложенный элемент. Можно выбрать родителя в форме или вернуть услугу на верхний уровень.')
table(['Структура','Поведение терминала'],[['Документы → Паспорт → Замена','Показывает последовательные экраны. Талон создаётся только при выборе «Замена».'],['Коммунальные услуги → Вода / Электричество','Посетитель выбирает нужную конечную услугу.'],['Отключённый родитель','Вся ветка скрыта и недоступна для новой выдачи. Старые ожидающие талоны сохраняются.']], [220,275])
p('У каждого элемента свой уникальный в точке префикс. Раздел с подуслугами не выдаёт новые талоны напрямую. Если подуслуги отключены, он не становится автоматически конечной услугой. Существующие услуги после миграции остаются на верхнем уровне, номера и история не переписываются.')
p('Циклы и связь с родителем другой компании/точки запрещены. В отчётах выбор родительской услуги включает её потомков по текущему дереву.')

chapter(13,'Сотрудники, роли и назначения')
p('Откройте «Персонал → Сотрудники». Для каждого работника создаётся отдельный логин. Email необязателен. Назначьте роль, точки и услуги; сохраните индивидуальный временный пароль. При первом входе сотрудник обязан его сменить.')
table(['Роль','Область'],[['Администратор компании','Все точки своей компании, настройки и отчёты; другие компании недоступны.'],['Администратор точки','Только назначенные точки, сотрудники STAFF в полностью доступной области. Повышать роль импортом нельзя.'],['Сотрудник','Только назначенные точки и услуги. Одна открытая смена и один активный клиент.']], [170,325])
p('Выбор родительской услуги разрешает её подуслуги. Выбор конкретной подуслуги не разрешает соседние. Пустой список услуг не означает «все»: такой сотрудник не сможет начать смену. Столы больше не используются.')
p('Один работник может иметь несколько точек. На рабочем месте он явно выбирает нужную точку до начала смены. Чтобы сменить назначения работающего сотрудника, сначала завершите его активного клиента и смену. Блокировка завершает сессии, но не удаляет талоны.')

chapter(14,'Массовый импорт CSV/XLSX')
steps('Скачать шаблон в «Персонал → Импорт сотрудников».','Заполнить firstName, lastName, login, email, role, companyBranchCode, branchCode, services. companyBranchCode - код филиала, branchCode - код точки.','Для повторяющихся в разных филиалах кодов точек обязательно указать companyBranchCode. В services - префиксы услуг; несколько значений разделять |. Один файл может содержать строки разных филиалов.','Загрузить CSV или XLSX и сопоставить столбцы. Выбрать поведение дубликатов: ошибка, пропустить или обновить.','Просмотреть строки и ошибки. Исправить неверные точки, услуги, роли или логины.','Подтвердить проверенные строки, сохранить отчёт и индивидуальные временные пароли.')
code(r'''firstName;lastName;login;email;role;companyBranchCode;branchCode;services
Айдана;Серик;aidana;;STAFF;CENTRAL;FLOOR1;A|B
Алексей;Иванов;alex;;STAFF;CENTRAL;FLOOR2;C''')
p('Подставьте реальные префиксы услуг соответствующих точек. Логин уникален внутри Runtime. Администратор точки не может импортом дать доступ к чужой точке или более высокой роли. Старая лишняя колонка desks игнорируется.')
p('Лимиты: файл до 5 МБ, до 200 строк сотрудников и 30 столбцов; распакованный XLSX до 30 МБ. Пароли показываются в ответе импорта и не сохраняются в отчёте задания. Если файл с ними потерян, сбросьте пароль конкретному пользователю.')

chapter(15,'Токены и привязка устройств к этажу')
p('Для каждого этажа удобнее выпускать отдельный короткий код с одной выбранной точкой. В админке компании: «Организация → Устройства → Добавить». Выберите название кода, доступные точки, типы TERMINAL/DISPLAY/WORKSTATION, лимит использований и срок.')
steps('На устройстве открыть URL Runtime /terminal, /display или /workstation.','Проверить адрес сервера. Ввести код и название устройства.','Выбрать точку по полному пути «Филиал / Точка», если код разрешает несколько. Для первого этажа выбрать CENTRAL / FLOOR1; одинаковый код в другом филиале - другая точка.','Подключить и перезагрузить страницу: повторный ввод кода не требуется.')
p('Подключение хранится в постоянной HttpOnly-cookie браузера. Истечение или отзыв регистрационного кода не отключает уже зарегистрированные устройства. Для этого нужен отдельный отзыв устройства. Очищенный профиль, incognito или удалённые cookie потребуют регистрации заново.')
note('Для терминала, дисплея и личной работы используйте отдельные устройства или отдельные постоянные профили браузера. Вкладки одного профиля разделяют cookie; регистрация второй точки в том же профиле может заменить первое подключение.')

chapter(16,'Терминал, киоск и принтер')
p('Откройте /terminal в постоянном профиле. Посетитель видит только услуги зарегистрированной точки, проходит подуслуги и выбирает конечную. Сначала талон сохраняется в PostgreSQL, затем открывается браузерная печать 80 мм.')
steps('Установить драйвер принтера и проверить тестовую печать средствами ОС.','Выбрать бумагу 80 мм и нужный принтер в браузере. Убрать ненужные колонтитулы.','Создать ярлык на адрес терминала, настроить автозапуск браузера по политике организации.','Включить F11 или управляемый kiosk-режим. Проверить работу после перезагрузки устройства.','Выдать пробный талон, проверить номер, услугу, точку и время на бумаге.')
p('Повторная печать использует тот же талон. Повторять выдачу вместо reprint не нужно. После отправки в печать терминал возвращается к услугам примерно через 15 секунд. При ошибке печати номер остаётся сохранённым.')
note('Обычный браузер не гарантирует бесшумную печать и не подтверждает физический выход бумаги. Возврат из диалога не доказывает успешную печать. Silent print зависит от администрируемых настроек браузера и принтера; отдельный print-agent не поставляется.')

chapter(17,'Дисплей очереди')
p('Откройте /display и зарегистрируйте его кодом нужной точки. Экран показывает текущие вызываемые номера с именем сотрудника и ожидающую очередь этой точки. Карточки столов и кнопки «На весь экран»/«Включить звук» убраны.')
bullets('Для полного экрана используйте F11 или управляемый kiosk.','Если браузер блокирует звук, один раз коснитесь экрана или нажмите клавишу. Звук также зависит от настроек компании/точки и аудиовыхода.','При обрыве остаётся последний снимок с отметкой отсутствия связи. Он может быть устаревшим; не считать его текущей очередью.','После восстановления соединения выполняется повторная синхронизация.')
p('На дисплей первого этажа не должны попадать услуги, ожидающие талоны или вызовы второго. Для переноса дисплея на другой этаж администратор отзывает подключение, затем устройство регистрируется заново в новой точке.')
p('Имена вызывающих сотрудников видны посетителям. Не используйте реальные пароли или другие закрытые сведения в названиях пользователей, устройств и точек.')

chapter(18,'Компьютер и рабочее место сотрудника')
p('Компьютер и сотрудник - разные сущности. При необходимости зарегистрируйте компьютер через /workstation, затем войдите личным логином на /staff. Cookie компьютера не заменяет пользовательскую сессию; смена сотрудника не требует повторной регистрации компьютера.')
steps('Открыть /staff. Ввести свой логин и пароль.','При первом входе сменить временный пароль на личный, не короче 12 символов.','Выбрать разрешённый филиал, затем его точку; проверить доступные услуги и подуслуги.','Нажать «Начать смену». Выбор стола не требуется.','Нажать «Вызвать следующего», затем «Начать обслуживание».','Завершить обслуживание или отметить неявку. В конце дня завершить смену.')
p('Если услуги не назначены, обратиться к администратору; самостоятельного расширения прав нет. Пока есть активный клиент, нельзя начать второго, уйти на паузу или закрыть смену. Несколько сотрудников одной услуги получают разных клиентов по FIFO.')

chapter(19,'Передача клиента и повтор команды')
p('Передача выполняется только внутри текущей точки. Получатель должен иметь открытую неприостановленную смену, быть свободным и иметь назначение нужной услуги или её родителя.')
steps('У текущего клиента выбрать получателя, при необходимости указать комментарий и отправить запрос.','До принятия клиент остаётся у отправителя. Получатель может принять или отклонить. Отправитель может отменить.','При принятии сервер повторно проверяет права и занятость. Сохраняются номер и история; меняется ответственный сотрудник.','Если срок запроса истёк, он закрывается без перемещения клиента. Передача между этажами как разными точками не выполняется.')
p('После сетевой ошибки команда может иметь неизвестный результат. Используйте «Повторить» для того же действия: сохраняется idempotency key и второй талон/вызов не создаётся. Не подменяйте неизвестную команду другим действием до выяснения результата.')
p('Повторный вызов клиента не сбрасывает первое время приглашения. При передаче интервалы участия разных сотрудников хранятся отдельно, поэтому общее число завершённых клиентов не удваивается.')

chapter(20,'Отчёты и формулы')
p('В админке открыть «Аналитика → Отчёты». Выбрать период, филиал, точку либо все доступные точки, сотрудника и услугу. Сводная таблица филиалов суммирует только их точки. Для конкретной услуги сначала выбрать её точку в верхнем переключателе. Родительская услуга включает потомков по текущему дереву. Администратор компании может получить общий отчёт по двум этажам; сотрудники ограничены собственной статистикой.')
table(['Показатель','Правило'],[['Выдано / завершено','Уникальные UUID талонов, выданных в периоде; завершено - из них со статусом COMPLETED.'],['Среднее ожидание','Среднее время от issuedAt до первого calledAt по вызванным талонам.'],['Среднее обслуживание','Для завершённого талона суммируются его закрытые интервалы, затем берётся среднее.'],['Участие сотрудника','Distinct ticketId его интервалов и сумма времени участия. Переданный талон может учитываться у двух участников.'],['Смены и паузы','Пересечение интервалов с выбранным периодом. Открытый интервал ограничивается текущим временем.']], [155,340])
p('Календарные даты интерпретируются в timezone компании, конец дня включается через начало следующего. Период максимум 366 дней. Это когорта по дате выдачи, а не только завершения. Экспорт CSV/XLSX содержит персональные данные; храните его по правилам организации.')

chapter(21,'Синхронизация и передача данных')
p('По умолчанию интерфейс опрашивает Runtime по HTTP примерно каждые 1,5 секунды. Одновременные запросы не накладываются; при ошибках интервал увеличивается до 15 секунд. Auto пробует Socket.IO и возвращается к HTTP при недоступном WebSocket. Команды всегда идут по HTTP.')
p('WebSocket-комнаты привязаны к точкам, а HTTP проверяет компанию, точку и роль. Изменение URL или заголовка не даёт устройству доступа к другому этажу. После reconnect загружается актуальный снимок.')
table(['Режим установки','Что получает Control Plane'],[['Managed','Техническое состояние, устройства и последние статусы обновлений. Списки сотрудников не передаются.'],['Isolated','ID, версия, режим, время контакта и технические статусы обновлений. Персональные сведения устройств/сотрудников не передаются.']], [105,390])
p('Bridge синхронизируется примерно раз в 30 секунд. Это последнее известное состояние, не общая оперативная очередь. При недоступности канала отзывы устройств остаются ожидающими. Runtime не останавливается из-за недоступной супер-админки.')

chapter(22,'Обновления и доступ владельца')
p('Обновления выполняет отдельный updater, не браузер сотрудника. Подписанный manifest проверяется публичным release key; архив проверяется по SHA-256, версии и protocol=2. GitHub token на сервере должен иметь только чтение нужного приватного репозитория.')
code(r'''node --env-file=.env.runtime --import tsx scripts/updater.ts''')
p('Случайное время проверки выбирается между 12:00 и 13:00 по timezone установки. Для применения нужны настроенные stop/start scripts, путь текущего релиза, pg_dump, backup конфигурации и MAINTENANCE_ENABLED=true. При активном вызове, обслуживании или печати установка откладывается. Для общего Runtime безопасный момент нужен сразу по всем точкам.')
p('Изолированная установка может загрузить подписанный архив и manifest вручную в «Система → Обновления». Загрузка ставит задание, не означает немедленного применения. Rollback приложения допустим только при совместимой схеме; база не откатывается автоматически.')
note('В текущей демонстрации канал GitHub и применение обновлений не настроены. Переход со старого updater v1 на Runtime v2 требует отдельной репетиции. Владелец может войти в Runtime только при явном ALLOW_OWNER_ACCESS=true и одноразовом подписанном разрешении; вход аудируется, универсального пароля нет.')

chapter(23,'Резервное копирование')
p('Резервная копия Runtime включает все компании и точки этой установки. Для Control Plane делается отдельная копия. Используйте совместимый pg_dump custom format, отдельный защищённый каталог и копию вне основного сервера.')
code(r'''node --env-file=.env.runtime --import tsx scripts/backup.ts runtime
node --env-file=.env.control --import tsx scripts/backup.ts control''')
p('Укажите PG_DUMP_PATH, если утилита не находится в PATH. Скрипт получает пароль через окружение дочернего процесса. Дополнительно сохраняйте конфигурацию, публичные ключи, версию приложения и, у владельца отдельно, защищённые приватные ключи.')
bullets('Назначить расписание backup и ответственного.','Проверять код завершения, размер файла, свободное место и уведомления о сбое.','Шифровать резервные копии и ограничить доступ.','Установить срок хранения по политике заказчика.','Регулярно восстанавливать копию на отдельном стенде: наличие файла само по себе не доказывает возможность восстановления.')
note('Не копируйте работающую папку PostgreSQL как обычную папку и не считайте это согласованной резервной копией. Не храните единственную копию на том же диске, что и рабочая база.')

chapter(24,'Восстановление после сбоя')
steps('Остановить изменения: Runtime и updater. Сохранить повреждённую базу и журналы для разбора.','Определить версию backup и совместимую версию приложения. Учесть данные, созданные после времени копии.','Создать новую UTF8-базу восстановления с другим именем. Не очищать рабочую базу вслепую.','Восстановить custom dump в новую базу. Пароль передать безопасным механизмом PostgreSQL.','На изолированном стенде проверить входы, точки, услуги, пользователей, талоны и отчёты.','Переключить конфигурацию на проверенную базу, запустить совместимое приложение, проверить health и устройства.','Запустить updater только после проверки и разрешения maintenance.')
code(r'''pg_restore --exit-on-error --no-owner \
  -h HOST -U USER -d NEW_DATABASE runtime.dump''')
p('Автоматического отката схемы и гарантии отсутствия потери данных после backup нет. Не запускайте migrate reset или destructive clean на рабочей базе. Сначала проверьте план восстановления. Отказ Control Plane восстанавливается отдельно и не требует удаления Runtime.')

chapter(25,'Диагностика: что проверить первым')
table(['Проблема','Проверка / действие'],[['Сайт не открывается','Питание, процесс, DNS/IP, порт, firewall, TLS. Отдельно /api/health каждого backend.'],['Этаж показывает чужую очередь','Проверить название точки на экране, cookie/профиль браузера и регистрацию устройства. При ошибке отозвать и зарегистрировать в правильной точке.'],['Нет нужной услуги','Выбрана ли точка; активны ли услуга и её родители; создана ли услуга именно здесь.'],['Сотрудник не начинает смену','Ему назначены услуги этой точки? Нет ли уже открытой смены в другой точке?'],['Нет получателя передачи','Тот же этаж/точка, открытая смена, нет паузы/клиента, есть допуск к услуге.'],['Талон не напечатан','Проверить принтер; использовать повторную печать того же талона, не создавать новый.'],['Нет WebSocket','Выбрать polling/Auto, проверить Upgrade proxy.'],['Обновление отложено','Есть активный клиент/печать, не то время, updater не настроен или применение выключено.']], [160,335])
p('Если браузер закрылся во время печати, PrintLease может блокировать обновление. После физической проверки ответственный оператор может подтвердить его через scripts/clear-print-lease.ts TICKET_UUID с окружением Runtime. Действие аудируется; автоматически подтверждать бумагу нельзя.')

chapter(26,'Приёмка двух этажей перед запуском')
steps('На терминале этажа 1 видны только его услуги и подуслуги. На терминале этажа 2 - только его.','Выдать талон на каждом этаже. Проверить, что UUID/очередь первого не появляется на втором дисплее и наоборот.','Вызвать клиента сотрудником этажа 1. Обновиться должен соответствующий дисплей; второй не должен показывать этот вызов.','Попытаться подключить устройство кодом с другой точкой или подменить точку запроса - доступ должен быть отклонён.','Проверить одного сотрудника с услугой-родителем и другого только с конкретной подуслугой.','Проверить конкурентный вызов двумя сотрудниками, передачу внутри точки и запрет межточечной передачи.','Перезагрузить устройства и Runtime: подключение, очередь и номера должны сохраниться.','Отключить Control Plane/внешний интернет при доступном локальном Runtime: локальные операции продолжаются.','Проверить реальные принтеры, звук, kiosk, CSV/XLSX, backup и пробное восстановление.','Зафиксировать результат и контакты ответственных. Только затем открывать доступ посетителям.')
note('В автоматических проверках используется отдельная тестовая база. Физический принтер, production Compose, GitHub-распространение и полный сценарий аварийного restore должны проверяться на оборудовании и инфраструктуре заказчика.')

chapter(27,'Ежедневная работа и быстрые ссылки')
table(['Кто','Действия'],[['Администратор','Проверить точки, устройства, активность услуг, назначения сотрудников и отчёты. Не менять структуру во время обслуживания без необходимости.'],['Сотрудник','Выбрать точку, проверить услуги, начать смену, вызывать/обслуживать, завершить клиента и смену.'],['Ответственный за оборудование','Проверить бумагу, принтеры, питание, сеть и браузерные профили.'],['Установщик','Контролировать health, backup, свободное место, сертификаты и согласованные обновления.']], [150,345])
table(['Интерфейс','Локальный пример'],[['Супер-админка','http://localhost:3002/owner'],['Админка компании','http://localhost:3001/admin'],['Сотрудник','http://localhost:3001/staff'],['Терминал / дисплей','http://localhost:3001/terminal /display'],['Регистрация компьютера / активация','/workstation /setup']], [175,320])
p('Ссылки localhost работают только на сервере, где запущена демонстрация. На других устройствах используйте реальный IP/домен Runtime. Последние выданные демонстрационные пароли и токены находятся в закрытом .local/demo-credentials.json и не включены в PDF. После личной смены пароля этот файл может содержать старое значение: используйте свой новый пароль или запросите сброс.')

chapter(28,'Приложение: параметры и команды')
table(['Параметр Runtime','Что задать'],[['RUNTIME_DATABASE_URL','URL собственной PostgreSQL-базы Runtime. Не URL Control Plane.'],['RUNTIME_ORIGINS / HOST','Адреса браузерного открытия / разрешённый интерфейс прослушивания.'],['COOKIE_SECURE','true при HTTPS.'],['INSTALLATION_ID / SETUP_SECRET','ID из Control Plane / собственный секрет установщика.'],['CONTROL_PUBLIC_KEY_FILE','Путь к доверенному публичному ключу активации/команд.'],['UPDATE_PUBLIC_KEY_FILE','Публичный ключ релизов.'],['BRIDGE_URL / BRIDGE_TOKEN','Разрешённый адрес Control Plane / серверный секрет установки; пустые значения отключают обмен.'],['ALLOW_OWNER_ACCESS','По умолчанию false; true только при согласованном административном доступе.'],['MAINTENANCE_ENABLED','По умолчанию false; true после настройки и rehearsal обновлений.']], [190,305])
code(r'''npm run check
npm test
npm run test:ui
npm run test:services
npm run test:restart''')
p('На текущем Windows-компьютере после перезагрузки: из D:\\OSPanel\\domains\\kezek запустить Node из .tools, затем .tools/start-v2-postgres.mjs (если 55433 ещё не занят), затем оба backend с --env-file=.env. Подробности в docs/LOCAL.md. Эти .tools - демонстрационные средства, не переносимая production-поставка.')
p('Необходимые документы исходников: INSTALLATION.md, EMPLOYEE-SERVICES.md, SERVICES.md, IMPORT.md, REPORTS.md, PRIVACY.md, UPDATES.md и STATUS.md. Этот PDF объединяет текущую практическую последовательность; перед внедрением сверяйте версию приложения.')

chapter(29,'Примеры: база, автозапуск и proxy')
p('Примеры для Linux с обычным Node.js, не Docker. Выполняет администратор сервера; реальные пути и имена служб зависят от ОС. Подставьте свои значения и проверьте на стенде.')
h('Создание отдельных баз в psql')
p('Под привилегированным администратором PostgreSQL создайте отдельных пользователей. Команда password запрашивает секрет интерактивно:')
code(r'''CREATE ROLE kezek_runtime LOGIN;
\password kezek_runtime
CREATE DATABASE kezek_runtime OWNER kezek_runtime
  ENCODING 'UTF8' TEMPLATE template0;
CREATE ROLE kezek_control LOGIN;
\password kezek_control
CREATE DATABASE kezek_control OWNER kezek_control
  ENCODING 'UTF8' TEMPLATE template0;''')
h('Пример /etc/systemd/system/kezek-runtime.service')
code(r'''[Unit]
Description=Kezek Runtime
After=network-online.target postgresql.service
[Service]
Type=simple
User=kezek
Group=kezek
WorkingDirectory=/opt/kezek/current
ExecStart=/usr/bin/node --env-file=/etc/kezek/runtime.env apps/runtime-api/dist/index.js
Restart=on-failure
RestartSec=5
NoNewPrivileges=true
[Install]
WantedBy=multi-user.target''')
p('Предварительно создайте системного пользователя kezek и разрешите ему читать код/конфигурацию и писать в .local. Node должен находиться по указанному пути. Для Control Plane создайте отдельную службу с control.env и apps/control-api/dist/index.js. Updater запускается отдельной службой и не должен останавливаться вместе с Runtime.')
code(r'''sudo systemctl daemon-reload
sudo systemctl enable --now kezek-runtime
sudo systemctl status kezek-runtime
sudo journalctl -u kezek-runtime -n 100 --no-pager''')

chapter(30,'Пример HTTPS reverse proxy')
p('Пример server-блока Nginx для уже выпущенного доверенного сертификата. Это шаблон, а не автоматическая установка TLS. Замените домен, пути и адрес backend. Не отключайте проверку сертификата на устройствах.')
code(r'''server {
  listen 443 ssl;
  server_name queue.example.kz;
  ssl_certificate     /etc/ssl/kezek/fullchain.pem;
  ssl_certificate_key /etc/ssl/kezek/private.key;
  client_max_body_size 310m;
  location / {
    proxy_pass http://127.0.0.1:3001;
    proxy_http_version 1.1;
    proxy_set_header Host $host;
    proxy_set_header X-Forwarded-Proto $scheme;
    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    proxy_set_header Upgrade $http_upgrade;
    proxy_set_header Connection "upgrade";
    proxy_read_timeout 75s;
  }
}''')
p('Для Control Plane используйте другой домен и порт 3002. В RUNTIME_ORIGINS и CONTROL_ORIGINS задайте соответствующие HTTPS-origin, COOKIE_SECURE=true. Настройку доверенного proxy и rate limit согласуйте с реальной сетью. Backend не следует открывать в интернет в обход proxy.')
code(r'''sudo nginx -t
sudo systemctl reload nginx''')
p('После настройки откройте health обоих приложений по HTTPS, проверьте вход, выдачу, дисплей, polling и Auto. Большой лимит тела нужен только для разрешённой загрузки offline-пакета администратором; импорт сотрудников по-прежнему ограничен 5 МБ на уровне API.')

chapter(31,'Запуск на текущем Windows-компьютере')
p('Этот раздел относится только к подготовленной демонстрации в D:\\OSPanel\\domains\\kezek. Средства .tools не являются production-установщиком. Рабочая база находится на 127.0.0.1:55433, а серверы - на 3001 и 3002.')
steps('Открыть PowerShell в корне проекта. Проверить, не запущена ли база.','Если порт 55433 уже слушается, второй PostgreSQL не запускать. Если база остановлена, выполнить команду запуска ниже и оставить окно открытым.','В двух других окнах PowerShell из этого же корня запустить Runtime и Control Plane.','Открыть health и страницы в браузере. После перезагрузки компьютера повторить запуск либо настроить согласованные службы.')
code(r'''Set-Location 'D:\OSPanel\domains\kezek'
Get-NetTCPConnection -LocalPort 55433 -State Listen
$node = '.\.tools\node-v22.16.0-win-x64\node.exe'
& $node .tools/start-v2-postgres.mjs''')
h('Два отдельных окна для приложений')
code(r'''# Окно 2, из корня проекта
$node = '.\.tools\node-v22.16.0-win-x64\node.exe'
& $node --env-file=.env apps/runtime-api/dist/index.js

# Окно 3, из корня проекта
$node = '.\.tools\node-v22.16.0-win-x64\node.exe'
& $node --env-file=.env apps/control-api/dist/index.js''')
p('Проверки: http://localhost:3001/api/health и http://localhost:3002/api/health должны вернуть ok=true. У Runtime ожидается version=1.1.0, protocol=2. Супер-админка: /owner на 3002; компания: /admin на 3001.')
note('На Windows перед полной пересборкой npm run build остановите backend-процессы: работающий Prisma engine может блокировать DLL генератора. После сборки примените новые миграции и запустите backend снова. Не удаляйте базу, .env и .local ради повторного запуска.')

chapter(32,'Филиал и точки: создание и перенос данных')
p('Филиал - самостоятельный родительский уровень. Для компании можно создать «Центральный», «Северный» и другие филиалы; в каждом - необходимое количество точек. Это не просто переименование списка точек.')
steps('Открыть «Организация → Филиалы», нажать «Добавить филиал», заполнить название, код и адрес.','У созданного филиала нажать «Точки обслуживания». Пока точек нет, список будет пустым.','Нажать «Добавить точку» и проверить выбранный филиал. Создать точку; повторить для остальных.','В верхней панели выбрать филиал. Второй переключатель показывает только его доступные точки. Филиал без точек пока не появляется в рабочем переключателе.','В выбранной точке настроить услуги, сотрудников и коды устройств. В назначениях и при регистрации показывается полный путь «Филиал / Точка».')
p('Администратор компании управляет филиалами и всеми их точками. Администратор точек получает доступ только к явно назначенным точкам, даже если рядом в том же филиале появилась новая. Автоматического расширения прав сотрудников при создании новой точки нет.')
p('При миграции для каждой прежней записи создан отдельный филиал с прежним названием; старая запись стала его сохранённой точкой. ID точек, регистрации устройств, сотрудники, талоны, услуги и история не менялись. Добавляйте новые точки в нужный филиал. При необходимости название старой точки можно изменить без сброса подключений.')
p('Филиал существующей точки менять нельзя: для другого филиала создайте новую точку. Очереди не перемещаются между филиалами или точками. Выключение филиала отключает доступ к его точкам; перед этим нужно завершить открытые смены. Реактивацию выполняет администратор компании.')
note('Внутреннее поле branchId в протоколе v2 по-прежнему означает ID точки; companyBranchId - ID её филиала. Существующие ссылки и cookie продолжают работать. Control Plane и Runtime имеют отдельные миграции этой структуры, подписанная активация передаёт филиалы вместе с точками.')

